'use strict';

/**
* Reflect the upper triangular part of a matrix `A` into the lower triangular part of another matrix `B`.
*
* @module @stdlib/blas-ext-base-gtriu2tril
*
* @example
* import gtriu2tril from '@stdlib/blas-ext-base-gtriu2tril';
*
* var A = [ 1.0, 2.0, 3.0, 4.0 ];
* var B = [ 0.0, 0.0, 0.0, 0.0 ];
*
* gtriu2tril( 'row-major', 2, 2, 0, A, 2, B, 2 );
* // B => [ 1.0, 0.0, 2.0, 4.0 ]
*
* @example
* import gtriu2tril from '@stdlib/blas-ext-base-gtriu2tril';
*
* var A = [ 1.0, 2.0, 3.0, 4.0 ];
* var B = [ 0.0, 0.0, 0.0, 0.0 ];
*
* gtriu2tril.ndarray( 2, 2, 0, A, 2, 1, 0, B, 2, 1, 0 );
* // B => [ 1.0, 0.0, 2.0, 4.0 ]
*/

// MODULES //

import setReadOnly from '@stdlib/utils-define-nonenumerable-read-only-property';
import main from './main.js';
import ndarray from './ndarray.js';


// MAIN //

setReadOnly( main, 'ndarray', ndarray );


// EXPORTS //

export default main;

// exports: { "ndarray": "main.ndarray" }
